SELECT "TableroSistemaPenal_5"."PAIS" AS "PAIS",   "TableroSistemaPenal_5"."SENTENCIA" AS "SENTENCIA",   COUNT(DISTINCT "TableroSistemaPenal_5"."ID_EVENTO") AS "ctd_ID_EVENTO_ok",   CAST(EXTRACT(YEAR FROM "TableroSistemaPenal_5"."FECHA_AUDIENCIA") AS BIGINT) AS "yr_FECHA_AUDIENCIA_ok" FROM "TableroSistemaPenal_5" WHERE ('Volver a Tramitacion Inicial' = 'Volver a Tramitacion Inicial') GROUP BY "TableroSistemaPenal_5"."PAIS",   "TableroSistemaPenal_5"."SENTENCIA", "yr_FECHA_AUDIENCIA_ok";
